def _credito(custo, icms_pct):
    """Mesma regra de apps/fiscal/tributos.py: ICMS sobre o custo, PIS/COFINS sobre o resto."""
    custo = Decimal(custo or 0)
    icms = custo * Decimal(icms_pct or 0) / 100
    base = custo - icms
    q = Decimal("0.000001")
    return {"credito_icms_kg": icms.quantize(q, ROUND_HALF_UP),
            "credito_pis_kg": (base * Decimal("0.0165")).quantize(q, ROUND_HALF_UP),
            "credito_cofins_kg": (base * Decimal("0.076")).quantize(q, ROUND_HALF_UP)}


def preencher(apps, schema_editor):
    """Lotes e movimentações que já existem ganham o crédito calculado com o
    ICMS de compra do produto (o mesmo que o sistema usava até aqui)."""
    Lote = apps.get_model("estoque", "Lote")
    Movimentacao = apps.get_model("estoque", "Movimentacao")
    for lote in Lote.objects.select_related("produto"):
        icms = lote.produto.icms_compra
        Lote.objects.filter(pk=lote.pk).update(icms_compra=icms, **_credito(lote.custo_unitario, icms))
    for mov in Movimentacao.objects.select_related("produto"):
        Movimentacao.objects.filter(pk=mov.pk).update(**_credito(mov.custo_unitario, mov.produto.icms_compra))



